mapper.select:
SELECT DISTINCT PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_ID || ':' || PTL_PORTFOLIO.PORTFOLIO_NAME text FROM PTL_PORTFOLIO LEFT JOIN PTL_CAPACCT_INFO ON PTL_CAPACCT_INFO.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID and PTL_CAPACCT_INFO.ACCT_TYPE = 'A01'
INVEST_YESORNO = 'Y' AND PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND PTL_PORTFOLIO.PORTFOLIO_ID != #{transferPortfolioId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue}
AND PTL_PORTFOLIO.MDATE > to_date(#{tradeDate},'yyyy-MM-dd')
